Fixpoint log_flat (E : env) (log : list sentry) : Prop :=
  match log with
  | [] => True
  | SE a w _ :: rest => (w <= 8)%nat /\ flat E a (Z.of_nat w) /\ log_flat E rest
  end.

(* [comment removed for export] *)
Lemma mem_denot_rm_out : forall E base a n log, log_flat E log -> flat E a (Z.of_nat n) ->
  forall x : word, (bv_unsigned x < bv_unsigned (adenot E a) \/ bv_unsigned (adenot E a) + Z.of_nat n <= bv_unsigned x)%Z ->
  mem_denot E base (log_rm a n log) x = mem_denot E base log x.
Proof.
