Lemma erange0_sound : forall segs E M kn e rlo rhi,
  know_ok segs E M kn -> erange0 kn e = Some (rlo, rhi) ->
  (rlo <= bv_unsigned (edenot E e) <= rhi)%Z.
Proof.
ltac2:(KReplay.run1 (kr_t_KXSound ()) ["KXFP"] "h01Eh11Mh21eh32knh43rhih53rloh64segsp;1p;4p;2p;3p;5p;:g01;Kj12Tg00fij10Tg00gNj11Tg00glj13Tg02ddj14Tg0686j4<Tg01RTj2;Tg08LPj28Tg01oIj47Tg02j6j26Tg00=;j35Tg08Ioj19Tg08MNj5:Tg08NQl:=Tg058X#2g00i5g00j1#0#0#0R0#0#0#0#1#3%10#3#4[g061n#2g00a0g00bLR0f6R1f5R2f4R3f3R4C<1;00R5#41834P0P0f2R6f1R7C7,6535f8R5f7R8P1%92g08OWP3P4P6P5P8P1P2P7D:f0M:=UUX40W5W2W3W1W0W6o"). Qed.

(* [comment removed for export] *)
Lemma deand_sound : forall E e e' s,
  deand e = (e', s) ->
