(* [comment removed for export] *)
Lemma lsplit_div_sound : forall kn m ts dts rts,
  lsplit_div kn m ts = (dts, rts) ->
  coeffs_divk kn m dts = true /\ forall E, tden E ts = (tden E dts + tden E rts)%Z.
