Lemma Forall_app_intro : forall {A} (P : A -> Prop) l1 l2,
  Forall P l1 -> Forall P l2 -> Forall P (l1 ++ l2).
Proof.
ltac2:(KReplay.run1 (kr_t_KXSound ()) ["KXFP"; "CarrySound"] "h01Ah11Ph22l1h32l2h42H1p;1p;3p;2p;4p200R0g0040R1p4p710p8P0g00:aR2p4p710p8P0g00;>p4p710R3p8g01;Kj13TP1j30TP2j31Tg00`UR2j22Tg05iSj45Tg02i[j44Tf0R1p-0[R4f1R5#3R6f2R7#3R8f3R9?075R:f4R;?095R<P2A19519097A0;97/2<R<[A0971,2:A1;7590;9[R:f5R2A129770;\<P9P7P5P1C5P1n2001000000120000000X38X26X14X03P:^38^26^14^03P1f6R1P2P;P9A012;A0129P7P5C4O5b4UUW3W2W1X00o"). Qed.


Lemma kzero_piece : forall E M (wb : expr) (wk : Z) w (V : word) (kk l0 i0 len : Z),
  flat E (SA wb wk) (Z.of_nat w) ->
  kentry_ok segs E M (KZero (SA wb kk) (ELit l0)) ->
  (0 <= i0)%Z -> (0 < len)%Z -> (i0 + len <= l0 mod 2 ^ 64)%Z ->
  ((kk + i0 + len <= wk)%Z \/ (wk + Z.of_nat w <= kk + i0)%Z) ->
  kentry_ok segs E (wbytes M (adenot E (SA wb wk)) (word_to_le_bytes w V))
            (KZero (SA wb (kk + i0)) (ELit len)).
Proof.
